  `fecha` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Disparadores `servicio_comentarios`
--
DELIMITER $$
CREATE TRIGGER `actualizar_promedio` AFTER INSERT ON `servicio_comentarios` FOR EACH ROW UPDATE servicios
SET promedio = (SELECT ROUND(AVG(rating),1)
                FROM servicio_comentarios
                WHERE servicio_id = NEW.servicio_id)
WHERE id = NEW.servicio_id
$$
DELIMITER ;

