--
-- Estructura para la vista `v_servicios_imagenes_pendientes`
--
DROP TABLE IF EXISTS `v_servicios_imagenes_pendientes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u516405553_u516405553_pac`@`127.0.0.1` SQL SECURITY DEFINER VIEW `v_servicios_imagenes_pendientes`  AS SELECT `s`.`id` AS `servicio_id`, `s`.`titulo` AS `titulo`, `s`.`categoria` AS `categoria`, `s`.`imagen` AS `imagen`, `s`.`imagen_estado` AS `imagen_estado`, `s`.`imagen_motivo` AS `imagen_motivo`, `s`.`fecha_publicacion` AS `created_at`, `a`.`id` AS `alumno_id`, `a`.`nombre` AS `alumno_nombre`, `a`.`correo` AS `alumno_correo`, `a`.`institucion` AS `alumno_institucion` FROM (`servicios` `s` left join `alumnos` `a` on(`a`.`id` = `s`.`alumno_id`)) WHERE `s`.`imagen_estado` in ('oculta','rechazada') ORDER BY `s`.`fecha_publicacion` DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_ultima_publicacion_por_alumno`
--
DROP TABLE IF EXISTS `v_ultima_publicacion_por_alumno`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u516405553_u516405553_pac`@`127.0.0.1` SQL SECURITY DEFINER VIEW `v_ultima_publicacion_por_alumno`  AS SELECT `a`.`id` AS `alumno_id`, greatest(ifnull((select max(`ap`.`fecha_subida`) from `apuntes` `ap` where `ap`.`id_alumno` = `a`.`id`),'1900-01-01'),ifnull((select max(`sv`.`fecha_publicacion`) from `servicios` `sv` where `sv`.`alumno_id` = `a`.`id`),'1900-01-01')) AS `ultima_publicacion` FROM `alumnos` AS `a` ;

